BEGIN;
CREATE TABLE IF NOT EXISTS forge_event_schema_families(id text PRIMARY KEY,tenant_id text REFERENCES tenants(id) ON DELETE RESTRICT,event_family text NOT NULL,compatibility_mode text NOT NULL DEFAULT 'BACKWARD' CHECK(compatibility_mode IN('BACKWARD','FORWARD','FULL','NONE')),unknown_field_policy text NOT NULL DEFAULT 'REJECT' CHECK(unknown_field_policy IN('REJECT','ALLOW')),producer_owner text NOT NULL,description text,created_by text NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
CREATE UNIQUE INDEX IF NOT EXISTS forge_event_schema_family_scope_uq ON forge_event_schema_families(coalesce(tenant_id,'__GLOBAL__'),event_family);
CREATE TABLE IF NOT EXISTS forge_event_schemas(id text PRIMARY KEY,family_id text NOT NULL REFERENCES forge_event_schema_families(id) ON DELETE RESTRICT,version integer NOT NULL CHECK(version>0),schema jsonb NOT NULL CHECK(jsonb_typeof(schema)='object'),fingerprint char(64) NOT NULL,status text NOT NULL DEFAULT 'DRAFT' CHECK(status IN('DRAFT','ACTIVE','DEPRECATED','REVOKED')),effective_at timestamptz,deprecated_at timestamptz,producer_owner text NOT NULL,consumer_owners text[] NOT NULL DEFAULT '{}',migration_metadata jsonb NOT NULL DEFAULT '{}'::jsonb,created_by text NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),UNIQUE(family_id,version),UNIQUE(family_id,fingerprint));
CREATE UNIQUE INDEX IF NOT EXISTS forge_event_schema_one_active_idx ON forge_event_schemas(family_id) WHERE status='ACTIVE';
CREATE INDEX IF NOT EXISTS forge_event_schema_active_idx ON forge_event_schemas(family_id,status,version DESC);
CREATE TABLE IF NOT EXISTS forge_event_schema_consumers(id text PRIMARY KEY,family_id text NOT NULL REFERENCES forge_event_schema_families(id) ON DELETE RESTRICT,tenant_id text REFERENCES tenants(id) ON DELETE RESTRICT,consumer_id text NOT NULL,owner text NOT NULL,supported_versions integer[] NOT NULL CHECK(cardinality(supported_versions)>0),preferred_version integer,minimum_version integer,maximum_version integer,active boolean NOT NULL DEFAULT true,last_seen_at timestamptz,metadata jsonb NOT NULL DEFAULT '{}'::jsonb,created_by text NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),UNIQUE(family_id,tenant_id,consumer_id));
CREATE INDEX IF NOT EXISTS forge_event_schema_consumer_idx ON forge_event_schema_consumers(family_id,tenant_id,active,consumer_id);
CREATE TABLE IF NOT EXISTS forge_event_schema_audit(id bigserial PRIMARY KEY,family_id text NOT NULL REFERENCES forge_event_schema_families(id) ON DELETE RESTRICT,schema_id text REFERENCES forge_event_schemas(id) ON DELETE RESTRICT,tenant_id text REFERENCES tenants(id) ON DELETE RESTRICT,actor text NOT NULL,action text NOT NULL,from_version integer,to_version integer,compatibility_mode text,details jsonb NOT NULL DEFAULT '{}'::jsonb,created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS forge_event_schema_audit_idx ON forge_event_schema_audit(tenant_id,family_id,created_at DESC);
CREATE TABLE IF NOT EXISTS forge_event_schema_quarantine(id text PRIMARY KEY,tenant_id text REFERENCES tenants(id) ON DELETE RESTRICT,project_id text REFERENCES projects(id) ON DELETE RESTRICT,event_family text NOT NULL,event_version integer,payload jsonb NOT NULL DEFAULT '{}'::jsonb,payload_fingerprint char(64),reason_code text NOT NULL,reason text NOT NULL,source text NOT NULL,source_id text,replay_of text,released_at timestamptz,released_by text,created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS forge_event_schema_quarantine_idx ON forge_event_schema_quarantine(tenant_id,event_family,created_at DESC);
DO $$ DECLARE r record; f text; s text; doc jsonb; BEGIN FOR r IN SELECT * FROM(VALUES('episode.state.changed',ARRAY['episodeId','projectId','state','revision']),('job.state.changed',ARRAY['jobId','projectId','kind','status']),('provider_run.state.changed',ARRAY['providerRunId','episodeId','status']),('publish.state.changed',ARRAY['publishRunId','episodeId','status']),('approval.created',ARRAY['approvalId','episodeId','stage','decision']),('qa.result.recorded',ARRAY['qaResultId','episodeId','status']),('security.audit.recorded',ARRAY['auditEventId','tenantId','action','outcome']),('artifact.created',ARRAY['artifactId','episodeId','kind']),('incident.state.changed',ARRAY['incidentId','tenantId','status','severity']),('workflow.plan.state.changed',ARRAY['planId','episodeId','templateVersionId','status']),('version.created',ARRAY['versionId','episodeId','kind']),('provider.callback',ARRAY['providerRunId','status']),('runner.callback',ARRAY['executionId','status']),('workflow.transition',ARRAY['episodeId','state','revision']),('reconciliation.request',ARRAY['scope','reason']))x(name,required_fields) LOOP f:='esf_'||md5('__GLOBAL__:'||r.name);s:='ess_'||md5(f||':1');doc:=jsonb_build_object('$schema','https://json-schema.org/draft/2020-12/schema','type','object','required',to_jsonb(r.required_fields),'additionalProperties',true);INSERT INTO forge_event_schema_families(id,tenant_id,event_family,compatibility_mode,unknown_field_policy,producer_owner,created_by) VALUES(f,NULL,r.name,'BACKWARD','ALLOW','forge-core','migration-024') ON CONFLICT DO NOTHING;INSERT INTO forge_event_schemas(id,family_id,version,schema,fingerprint,status,effective_at,producer_owner,created_by) VALUES(s,f,1,doc,encode(digest(doc::text,'sha256'),'hex'),'ACTIVE',now(),'forge-core','migration-024') ON CONFLICT DO NOTHING;END LOOP;END $$;
COMMIT;
